<template>
  <main class="briefing-page">
    <header class="heading"><div><span class="eyebrow">AI管理决策</span><h1>AI简报</h1><p>阅读专家预设任务的正式保存结果，查看依据，再进入问策。</p></div><div><el-button @click="router.push('/admin/reports/advice')">专家问策</el-button><el-button v-if="canManage" @click="router.push({path:'/admin/system/expert-management',query:{expertId:current?.expertId||'course',section:'presets'}})">维护预设任务</el-button></div></header>
    <div class="filters"><el-select v-model="semesterId" clearable placeholder="全部学期" aria-label="简报学期"><el-option v-for="s in options.semesters" :key="s.id" :value="s.id" :label="s.name" /></el-select><el-select v-model="collegeId" clearable placeholder="授权开课院系" aria-label="简报开课院系"><el-option v-for="c in options.colleges" :key="c.id" :value="c.id" :label="c.name" /></el-select><el-switch v-model="showHistory" active-text="含历史及撤回结果" /><el-button :loading="loading" @click="loadList">刷新保存结果</el-button></div>
    <p class="muted">学院按课程的开课院系确定。打开页面和刷新列表读取已保存内容，不启动数据分析。</p>
    <div v-if="error" class="notice error" role="alert">{{ error }} <el-button link @click="loadList">重新加载</el-button></div>
    <el-empty v-if="!loading&&!items.length&&!error" description="当前范围暂无正式简报。维护者可先保存预设、试跑，再人工正式生成。" />
    <div class="briefing-layout" v-if="items.length">
      <nav class="publication-list" aria-label="简报列表"><button v-for="item in items" :key="item.publicationId" :class="{selected:current?.publicationId===item.publicationId}" @click="open(item.publicationId)"><span class="list-title">{{ item.name || item.question || '课程首修观察' }}</span><small>{{ scopeLabel(item) }}</small><small>保存于 {{ date(item.publishedAt||item.createdAt) }}</small><el-tag size="small" effect="plain" :type="invalid(item)?'warning':'info'">{{ invalid(item)?'历史失效':item.applicable===false?'旧分析条件':'正式保存' }}</el-tag></button><el-pagination small layout="prev, pager, next" :page-size="20" :total="total" :current-page="page" @current-change="page=$event;loadList()" /></nav>
      <section v-loading="detailLoading" class="publication-detail">
        <template v-if="current">
          <header class="detail-heading"><div><h2>{{ current.name || current.question || '课程首修观察' }}</h2><p>{{ scopeLabel(current) }} · 保存时间 {{ date(current.publishedAt||current.createdAt) }}</p></div><el-button v-if="canManage&&!invalid(current)" type="danger" plain @click="withdrawOpen=true;withdrawReason=''">撤回</el-button></header>
          <div v-if="invalid(current)" class="notice warning"><b>这份简报已失效</b><p>{{ current.withdrawReason || current.invalidReason || '已撤回或依据失效。历史保留，可查看当时内容；无法再用于有效问策引用。' }}</p></div>
          <div v-else-if="current.applicable===false||current.currentAnalysisConditions===false" class="notice warning">本结果属于旧分析条件，可复看当时事实。当前分析条件的正式结果以简报列表为准。</div>
          <div v-if="current.replacesPublicationId" class="notice"><b>本次为重新查询后保存的修正结果</b><p>原简报及撤回记录保留，可对照两次结果。</p><el-button link @click="showHistory=true;router.push({path:route.path,query:{...route.query,publicationId:current.replacesPublicationId}})">查看被修正的原简报</el-button></div>
          <div class="status-strip"><span>事实：{{ factLabel }}</span><span>解释：{{ explanationLabel }}</span><span>来源时间：{{ current.dataUpdatedAt ? date(current.dataUpdatedAt) : '未知，以各层来源记录为准' }}</span></div>
          <p v-if="current.run" class="muted">本次触发：{{ triggerLabel(current.run.trigger) }} · 执行编号 {{ current.run.executionId||current.run.id }} · {{ current.run.workerFinished===false?'解释或工作进程尚未结束':'工作进程已结束' }}</p>
          <section class="overview" v-if="observation"><h3>{{ publishMode==='observation'?'已接入课程的首修观察':'当前可支持的事实' }}</h3><div class="fact-grid"><div><span>有效课程</span><b>{{ observation.validCourseCount ?? observation.evaluableCourseCount ?? result.coverage?.evaluablePopulation ?? '未确认' }}</b></div><div><span>同范围首修参照</span><b>{{ rate(observation.referenceRate) }}</b><small>{{ observation.referencePassed ?? '未知' }}/{{ observation.referenceAttempts ?? '未知' }} 人次</small></div><div><span>进入观察的课程</span><b>{{ observation.observedCourseCount ?? observedRows.length }}</b></div><div><span>排除或待核记录</span><b>{{ observation.excludedCount ?? observation.excludedCourseCount ?? result.coverage?.unknownCount ?? '未确认' }}</b></div></div><p>按同范围首修人次加权参照，选入“首修未通过人次大于0且首修通过率低于参照”的课程。按未通过人次、实际通过率、课程编号排序。</p><p class="boundary">这是已接入记录的限定观察；人次包含不同学生的选课记录，不能当作唯一学生人数，也不能据此认定教学质量或原因。</p></section>
          <div v-if="publishMode==='facts_only'" class="notice warning">本次仅发布已有依据的原字段事实。未满足口径、登记或验证条件的新推导不会成为观察结论。<p v-for="reason in result.publicationGate?.reasons||[]" :key="reason">{{ reason }}</p></div>
          <p v-if="result.validationBasis?.threeLayerCheck?.unknownFirstPassAttempts" class="notice warning">本次数据中有 {{ result.validationBasis.threeLayerCheck.unknownFirstPassAttempts }} 个首修人次结果尚未明确，未计入首修通过率，也未计作首修未通过。</p>
          <section v-if="observedRows.length&&publishMode==='observation'" class="observations"><div class="section-heading"><h3>建议进一步查看的课程</h3><el-button link @click="showAll=!showAll">{{ showAll?'收起至前5项':`展开全部${observedRows.length}项` }}</el-button></div><p class="muted">选入依据只说明相对于同范围参照的位置，不推断原因。</p><div class="table-scroll"><table><thead><tr><th>课程</th><th>首修通过率</th><th>首修未通过人次</th><th>首修人次</th><th>下一步</th></tr></thead><tbody><tr v-for="row in visibleObservations" :key="row.course_id"><td><b>{{ row.course_name || row.course_id }}</b><small>{{ row.course_id }}</small></td><td>{{ row.first_pass_pct!=null?`${row.first_pass_pct}%`:rate(row.firstPassRate ?? row.first_pass_rate) }}</td><td>{{ row.first_unpassed ?? '未知' }}</td><td>{{ row.first_attempts ?? row.firstAttempts ?? '未知' }}</td><td><el-button link @click="inspect(row)">查看依据</el-button><el-button link :disabled="invalid(current)||current.applicable===false||current.currentAnalysisConditions===false" @click="ask(row)">继续问策</el-button></td></tr></tbody></table></div></section>
          <div v-else-if="publishMode==='observation'" class="notice">{{ ({no_data:'本范围未返回聚合记录，请核对数据准备情况。',no_valid_courses:'本次没有口径可核的有效课程，无法建立参照。',one_course:'本范围仅一门有效课程，无法形成有意义的范围观察。',no_observations:'本次没有课程低于同范围参照并满足选入条件。'} as Record<string,string>)[result.observationState] || '本次没有课程进入观察集合。' }} 请结合有效课程数、排除项和来源覆盖阅读，不能据此认定不存在教学问题。</div>
          <section v-if="result.validationBasis" class="validation"><h3>数据核对</h3><p>冻结输入独立复算：{{ validationLabel(result.validationBasis.independentRecompute || result.validationBasis.recomputation) }}</p><p>三层加工关系核对：{{ validationLabel(result.validationBasis.threeLayerCheck || result.validationBasis.threeLayer) }}</p><p class="muted">复算通过与三层加工关系正确分别记录；查询时点不可比时保持待核。</p></section>
          <div class="reading-actions"><el-button @click="inspectedCourse=null;evidenceOpen=true">查看完整事实、来源与证据</el-button><el-button :disabled="invalid(current)||current.applicable===false||current.currentAnalysisConditions===false" @click="ask()">围绕这份结果问策</el-button></div>
          <section v-if="current.latestExecution" class="notice"><b>最近尝试：{{ stateLabel(current.latestExecution.state) }}</b><p>{{ current.latestExecution.summary }}</p><small>最近尝试与这份已保存事实分别记录；失败不会重写原数据时间。</small></section>
          <section v-if="result.interpretation||current.explanation||selectedExplanation?.mode==='validated_references'" class="interpretation"><h3>结果解释</h3><p v-if="result.interpretation||current.explanation">{{ current.explanation?.text || result.interpretation?.text || result.interpretation?.summary || (typeof result.interpretation==='string'?result.interpretation:'') }}</p><p v-for="fact in explanationFacts" :key="fact.factId">{{ fact.label||fact.title||fact.factId }}：{{ fact.value ?? fact.displayValue ?? '见原事实' }} {{ fact.unit||'' }}</p><p v-if="selectedExplanation?.mode==='validated_references'" class="muted">真实模型选择已有事实引用；原计算数字和判断边界保留。</p></section>
        </template>
      </section>
    </div>
    <el-drawer v-model="evidenceOpen" title="原保存结果与数据依据" size="min(920px,96vw)">
      <section v-if="inspectedCourse" aria-label="所选课程的观察依据" class="overview">
        <h3>{{ inspectedCourse.course_name || inspectedCourse.course_id }} · 观察次序 {{ observedRows.findIndex(row=>String(row.course_id)===String(inspectedCourse?.course_id))+1 }}/{{ observedRows.length }}</h3>
        <p>以下数字来自这份已保存简报，未重新查询当前数据库。</p>
        <div class="fact-grid"><div><span>首修人次 N</span><b>{{ inspectedCourse.first_attempts }}</b></div><div><span>首修通过人次 P</span><b>{{ inspectedCourse.first_pass }}</b></div><div><span>首修未通过人次 U=N−P</span><b>{{ inspectedCourse.first_unpassed }}</b></div><div><span>首修通过率 P/N</span><b>{{ rate(inspectedCourse.first_pass_pct) }}</b></div></div>
        <p>选入依据：首修未通过人次 {{ inspectedCourse.first_unpassed }} 大于0；首修通过率 {{ rate(inspectedCourse.first_pass_pct) }} 低于同范围参照 {{ rate(observation?.referenceRate) }}。排序先比较未通过人次，再比较未四舍五入的通过率和课程编号。</p>
        <p class="boundary">当前范围 {{ current?scopeLabel(current):'' }}。这个位置表示进一步核对的顺序，不能据此确认教学原因或评价教师。</p>
      </section>
      <details :open="!inspectedCourse"><summary>查看完整保存事实、三层来源和核对记录</summary><RunResult v-if="current?.outcome" :run="current.outcome" :publication-id="current.publicationId" :options="options" mode="research" /></details>
    </el-drawer>
    <el-dialog v-model="withdrawOpen" title="撤回正式简报" width="min(560px,94vw)"><p>历史事实和原因保留，撤回后移出当前结果，问策引用将失效。</p><label class="reason"><span>撤回原因（必填）</span><el-input v-model="withdrawReason" type="textarea" :rows="4" maxlength="1000" /></label><p v-if="withdrawError" class="error">{{ withdrawError }}</p><template #footer><el-button :disabled="withdrawing" @click="withdrawOpen=false">取消</el-button><el-button type="danger" :disabled="!withdrawReason.trim()" :loading="withdrawing" @click="withdraw">确认撤回</el-button></template></el-dialog>
  </main>
</template>
<script setup lang="ts">
import {computed,onBeforeUnmount,onMounted,ref,watch} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {authStore} from '@/store/auth'
import {expertResourcesApi as api,explanationStateLabel,type BriefingPublication} from '@/api/aiDecision/expertResources'
import type {ResourceOptions} from '@/types/expertResources'
import RunResult from '../expert-resources/RunResult.vue'
const router=useRouter(),route=useRoute(),options=ref<ResourceOptions>({plans:[],semesters:[],colleges:[]}),items=ref<BriefingPublication[]>([]),current=ref<BriefingPublication|null>(null),total=ref(0),page=ref(1),semesterId=ref(''),collegeId=ref(''),showHistory=ref(false),loading=ref(false),detailLoading=ref(false),error=ref(''),canManage=ref(false),showAll=ref(false),evidenceOpen=ref(false),inspectedCourse=ref<Record<string,any>|null>(null),withdrawOpen=ref(false),withdrawReason=ref(''),withdrawError=ref(''),withdrawing=ref(false)
let listRequest=0,detailRequest=0,identityEpoch=0;const sequences=new Map<string,{sequence:number;revision:number;explanationVersion:number}>();let withdrawRequestId=''
const result=computed(()=>current.value?.outcome?.result||{}),observation=computed<Record<string,any>|null>(()=>result.value.observationBaseline?{referenceAttempts:result.value.observationBaseline.firstAttempts,referencePassed:result.value.observationBaseline.firstPass,referenceRate:result.value.observationBaseline.ratePct,validCourseCount:result.value.observationBaseline.courseCount,observedCourseCount:result.value.observationCount,excludedCount:result.value.observationExclusions?.length}:null)
const observedRows=computed<Record<string,any>[]>(()=>Array.isArray(result.value.observations)?result.value.observations:[]),visibleObservations=computed(()=>showAll.value?observedRows.value:observedRows.value.slice(0,5)),publishMode=computed(()=>result.value.publishMode||current.value?.publishMode||'facts_only')
const selectedExplanation=computed(()=>current.value?.explanations?.at(-1)?.explanation||result.value.explanation),explanationFacts=computed(()=>Array.isArray(result.value.facts)?result.value.facts.filter((fact:Record<string,any>)=>selectedExplanation.value?.factIds?.includes(fact.factId)):[])
const factLabel=computed(()=>publishMode.value==='observation'?'已保存限定观察':publishMode.value==='facts_only'?'已保存原字段事实':'发布受阻'),explanationLabel=computed(()=>explanationStateLabel(current.value?.explanationState))
function date(value?:string){if(!value)return '未记录';const d=new Date(value);return Number.isNaN(d.getTime())?value:d.toLocaleString('zh-CN',{hour12:false,timeZone:'Asia/Shanghai'})}
function rate(value:unknown){if(value==null)return '未知';const n=Number(value);return Number.isFinite(n)?`${n.toFixed(2)}%`:'未知'}
function invalid(p:BriefingPublication){return ['withdrawn','invalid'].includes(p.state||p.status||'')||p.valid===false}
function stateLabel(state:string){return ({queued:'等待执行',running:'执行中',completed:'已完成',partial:'部分完成',blocked:'条件未满足',failed:'失败',cancelled:'已取消'} as Record<string,string>)[state]||state}
function triggerLabel(trigger?:string){if(!trigger)return '未记录';return trigger==='manual'?'人工执行':trigger.startsWith('test:')?'真实5分钟到期（验证用途）':trigger.startsWith('weekly:')?'真实每周到期':trigger.startsWith('initial:')?'自动启用首期':trigger.startsWith('recovery:')?'恢复补跑':trigger}
function validationLabel(basis:unknown){if(typeof basis==='string')return basis;if(!basis||typeof basis!=='object')return '待核，原结果未提供明确结论';const b=basis as Record<string,any>;return `${({passed:'通过',pending:'待核',non_comparable:'时点不可比',equal_current:'当次数字与字段一致，历史批次可比性未知',failed:'发现矛盾',unknown:'待核',verified:'通过'} as Record<string,string>)[b.state||b.status]||b.state||b.status||'待核'}${b.reason||b.note?` · ${b.reason||b.note}`:''}`}
function scopeLabel(p:BriefingPublication){const input=p.input||p.outcome?.input||p.outcome?.result?.scope||p.scope||{};return [options.value.semesters.find(s=>String(s.id)===String(input.semester_id))?.name||input.semester_name||'指定业务学期',options.value.colleges.find(c=>String(c.id)===String(input.college_id))?.name||input.college_name||(input.college_id?'指定开课院系':'授权范围')].join(' · ')}
async function loadList(){const request=++listRequest,epoch=identityEpoch;loading.value=true;error.value='';try{const response=await api.publications({semesterId:semesterId.value,collegeId:collegeId.value,history:showHistory.value,offset:(page.value-1)*20,limit:20});if(request!==listRequest||epoch!==identityEpoch)return;items.value=response.items;total.value=response.total;const selected=String(route.query.publicationId||current.value?.publicationId||response.items[0]?.publicationId||'');if(selected)void open(selected);else current.value=null}catch(e){if(request===listRequest)error.value=(e as Error).message}finally{if(request===listRequest)loading.value=false}}
async function open(id:string){const request=++detailRequest,epoch=identityEpoch;detailLoading.value=true;error.value='';try{const value=await api.publication(id);if(request!==detailRequest||epoch!==identityEpoch)return;const old=sequences.get(id);if(old&&(value.publicationSequence<old.sequence||value.publicationSequence===old.sequence&&(value.revision<old.revision||(value.explanationVersion||0)<old.explanationVersion)))return;sequences.set(id,{sequence:value.publicationSequence,revision:value.revision,explanationVersion:value.explanationVersion||0});current.value=value;showAll.value=false;withdrawOpen.value=false;void router.replace({path:route.path,query:{...route.query,publicationId:id}})}catch(e){if(request===detailRequest){error.value=(e as Error).message;current.value=null}}finally{if(request===detailRequest)detailLoading.value=false}}
function inspect(row:Record<string,any>){inspectedCourse.value=row;evidenceOpen.value=true}
function ask(row?:Record<string,any>){if(!current.value||invalid(current.value)||current.value.applicable===false)return;void router.push({path:'/admin/reports/advice',query:{publicationId:current.value.publicationId,objectId:row?.course_id,objectName:row?.course_name,question:row?`说明${row.course_name||row.course_id}为何进入观察范围，核对数据依据和判断边界。`:'说明这份课程首修观察的选入依据、数据可核性与判断边界。'}})}
async function withdraw(){if(!current.value||!withdrawReason.value.trim())return;withdrawing.value=true;withdrawError.value='';withdrawRequestId ||= crypto.randomUUID();try{const value=await api.withdrawPublication(current.value.publicationId,current.value.revision,withdrawReason.value,withdrawRequestId);current.value=value;withdrawOpen.value=false;withdrawRequestId='';showHistory.value=true;await loadList()}catch(e){withdrawError.value=(e as Error).message}finally{withdrawing.value=false}}
async function initialize(){const epoch=identityEpoch;const responses=await Promise.allSettled([api.options(),api.catalog()]);if(epoch!==identityEpoch)return;if(responses[0].status==='fulfilled')options.value=responses[0].value;if(responses[1].status==='fulfilled')canManage.value=!!responses[1].value.canManage;await loadList()}
watch([semesterId,collegeId,showHistory],()=>{page.value=1;void loadList()})
watch(()=>route.query.publicationId,id=>{if(id&&String(id)!==current.value?.publicationId)void open(String(id))})
watch(()=>[authStore.user?.username,authStore.user?.activeIdentityId,authStore.user?.permissionContext?.scopeFingerprint].join('|'),()=>{identityEpoch++;items.value=[];current.value=null;sequences.clear();canManage.value=false;evidenceOpen.value=false;withdrawOpen.value=false;error.value='';if(authStore.user)void initialize()})
onMounted(initialize);onBeforeUnmount(()=>{identityEpoch++;listRequest++;detailRequest++})
</script>
